    SELECT TB_EVTBOX_SEQ.NEXTVAL
      FROM DUAL

/* setUserStatusEvent */
INSERT INTO TB_EVTBOX (
            EVNT_NUMB
          , EVNT_TYPE
          , USER_NUMB
          , SPND_NUMB
          , REGI_DATE
) VALUES (  #{evntNumb}
          , #{evntType}
          , #{userNumb}
          , #{spndNumb}
          , SYSDATE
)

mapper.update:


UPDATE /* uptSuspensionSyncCompleted */
       TH_USSPND S
   SET S.SYNC_STAT = #{suspensionSyncCompleted}
 WHERE S.SPND_NUMB = #{spndNumb}
   AND S.SYNC_STAT = #{suspensionSyncPending}
   AND NOT EXISTS (
           SELECT 1
             FROM TB_EVTBOX E
            WHERE E.SPND_NUMB = S.SPND_NUMB
              AND E.EVNT_NUMB > #{evntNumb}
       )

mapper.delete:
DELETE /* delUserStatusEvent */
  FROM TB_EVTBOX
 WHERE EVNT_NUMB = #{evntNumb}
